if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save'])){verify_csrf();$id=(int)$_POST['game_id'];$status=in_array($_POST['status'],['scheduled','live','completed'],true)?$_POST['status']:'scheduled';$s1=$_POST['score1']===''?null:max(0,(int)$_POST['score1']);$s2=$_POST['score2']===''?null:max(0,(int)$_POST['score2']);$db=db();$db->beginTransaction();$q=$db->prepare('UPDATE games SET score1=?,score2=?,status=?,updated_at=datetime(\'now\') WHERE id=?');$q->execute([$s1,$s2,$status,$id]);$db->prepare('DELETE FROM pitchers WHERE game_id=?')->execute([$id]);$db->prepare('DELETE FROM batters WHERE game_id=?')->execute([$id]);$qp=$db->prepare('INSERT INTO pitchers(game_id,name,team,rl,runs_allowed,earned_runs) VALUES(?,?,?,?,?,?)');foreach($_POST['p_name']??[] as $i=>$name)if(trim($name)!=='')$qp->execute([$id,trim($name),trim($_POST['p_team'][$i]),(float)$_POST['p_rl'][$i],(int)$_POST['p_ra'][$i],(int)$_POST['p_er'][$i]]);$qb=$db->prepare('INSERT INTO batters(game_id,name,team,h,tb,ab,rbi) VALUES(?,?,?,?,?,?,?)');foreach($_POST['b_name']??[] as $i=>$name)if(trim($name)!=='')$qb->execute([$id,trim($name),trim($_POST['b_team'][$i]),(int)$_POST['b_h'][$i],(int)$_POST['b_tb'][$i],(int)$_POST['b_ab'][$i],(int)$_POST['b_rbi'][$i]]);$qm=$db->prepare('INSERT INTO mvp(game_id,name,team,notes) VALUES(?,?,?,?) ON CONFLICT(game_id) DO UPDATE SET name=excluded.name,team=excluded.team,notes=excluded.notes');$qm->execute([$id,trim($_POST['mvp_name']),trim($_POST['mvp_team']),trim($_POST['mvp_notes'])]);$db->commit();update_finalists();header('Location: admin.php?game='.$id.'&saved=1');exit;}
