lect></label><label>Score <?=h($g['team1'])?><input type="number" min="0" name="score1" value="<?=h((string)$g['score1'])?>"></label><label>Score <?=h($g['team2'])?><input type="number" min="0" name="score2" value="<?=h((string)$g['score2'])?>"></label></div></section><section class="card"><div class="toolbar"><h2>Pitchers</h2><button type="button" class="btn alt" data-add="#pitchers" data-template="#pitch-template">Add pitcher</button></div><div id="pitchers"><?php foreach($pitch as $p):?><div class="statrow pitchrow"><input name="p_name[]" placeholder="Name" value="<?=h($p['name'])?>"><input name="p_team[]" placeholder="Team" value="<?=h($p['team'])?>"><input type="number" step="0.1" min="0" name="p_rl[]" placeholder="RL" value="<?=$p['rl']?>"><input type="number" min="0" name="p_ra[]" placeholder="Runs allowed" value="<?=$p['runs_allowed']?>"><input type="number" min="0" name="p_er[]" placeholder="PGL / ER" value="<?=$p['earned_runs']?>"><button type="button" class="btn alt" data-remove>Remove</button></div><?php endforeach?></div></section><section class="card"><div class="toolbar"><h2>Batters</h2><button type="button" class="btn alt" data-add="#batters" data-template="#batter-template">Add batter</button></div><div id="batters"><?php foreach($bat as $b):?><div class="statrow"><input name="b_name[]" placeholder="Name" value="<?=h($b['name'])?>"><input name="b_team[]" placeholder="Team" value="<?=h($b['team'])?>"><input type="number" min="0" name="b_h[]" placeholder="H" value="<?=$b['h']?>"><input type="number" min="0" name="b_tb[]" placeholder="TB" value="<?=$b['tb']?>"><input type="number" min="0" name="b_ab[]" placeholder="AB" value="<?=$b['ab']?>"><input type="number" min="0" name="b_rbi[]" placeholder="RBI" value="<?=$b['rbi']?>"><button type="button" class="btn alt" data-remove>Remove</button></div><?php endforeach?></div></section><section class="card"><h2>Match MVP</h2><div class="formgrid"><label class="wide">Name<input name="mvp_name" value="<?=h($mvp['name'])?>"></label><label class="wide">Team<input name="mvp_team" value="<?=h($mvp['team'])?>"></label><label class="full">Notes<textarea name="mvp_notes" rows="3"><?=h($mvp['notes'])?></textarea></label></div></section><button class="btn" name="save" value="1">Save and publish</button></form></main><template id="pitch-template"><div class="statrow pitchrow"><input name="p_name[]" placeholder="Name"><input name="p_team[]" placeholder="Team"><input type="number" step="0.1" min="0" name="p_rl[]" placeholder="RL"><input type="number" min="0" name="p_ra[]" placeholder="Runs allowed"><input type="number" min="0" name="p_er[]" placeholder="PGL / ER"><button type="button" class="btn alt" data-remove>Remove</button></div></template><template id="batter-template"><div class="statrow"><input name="b_name[]" placeholder="Name"><input name="b_team[]" placeholder="Team"><input type="number" min="0" name="b_h[]" placeholder="H"><input type="number" min="0" name="b_tb[]" placeholder="TB"><input type="number" min="0" name="b_ab[]" placeholder="AB"><input type="number" min="0" name="b_rbi[]" placeholder="RBI"><button type="button" class="btn alt" data-remove>Remove</button></div></template><script src="assets/app.js"></script></body></html>